@Immutable
data class ProductUiState(
    val isLoading: Boolean = false,
    val products: List<Product> = emptyList(),
    val error: String? = null
)

sealed interface ProductUiIntent {
    data object LoadProducts : ProductUiIntent
    data class OnProductClick(val id: String) : ProductUiIntent
    data object Refresh : ProductUiIntent
}

sealed interface ProductUiEffect {
    data class NavigateToDetail(val id: String) : ProductUiEffect
}

class ProductViewModel(private val repo: ProductRepository) : ViewModel() {
    private val _uiState = MutableStateFlow(ProductUiState())
    val uiState: StateFlow<ProductUiState> = _uiState.asStateFlow()

    private val _effect = MutableSharedFlow<ProductUiEffect>(replay = 0, extraBufferCapacity = 1)
    val effect: SharedFlow<ProductUiEffect> = _effect.asSharedFlow()

    fun onIntent(intent: ProductUiIntent) {
        when (intent) {
            is ProductUiIntent.LoadProducts -> loadProducts()
            is ProductUiIntent.OnProductClick -> navigateToDetail(intent.id)
            is ProductUiIntent.Refresh -> loadProducts()
        }
    }

    private fun loadProducts() {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true, error = null) }
            try {
                val products = withContext(Dispatchers.IO) { repo.getProducts() }
                _uiState.update { it.copy(isLoading = false, products = products) }
            } catch (e: Exception) {
                _uiState.update { it.copy(isLoading = false, error = e.message) }
            }
        }
    }

    private fun navigateToDetail(id: String) {
        viewModelScope.launch { _effect.emit(ProductUiEffect.NavigateToDetail(id)) }
    }
}

@Composable
fun ProductScreen(
    onNavigateToDetail: (String) -> Unit,
    viewModel: ProductViewModel = koinViewModel()
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val context = LocalContext.current
    LaunchedEffect(Unit) {
        viewModel.effect.collect { effect ->
            when (effect) {
                is ProductUiEffect.NavigateToDetail -> onNavigateToDetail(effect.id)
            }
        }
    }
    ProductContent(uiState = uiState, onIntent = viewModel::onIntent)
}

