class BikeStatusViewModel(
    private val bleManager: BleManager
) : ViewModel() {
    private val _uiState = MutableStateFlow(BikeStatusUiState())
    val uiState: StateFlow<BikeStatusUiState> = _uiState.asStateFlow()

    private var currentListener: BikeStatusListener? = null

    fun onEvent(intent: BikeStatusUiIntent) {
        when (intent) {
            is BikeStatusUiIntent.StartMonitoring -> startMonitoring()
            is BikeStatusUiIntent.StopMonitoring -> stopMonitoring()
        }
    }

    private fun startMonitoring() {
        currentListener?.let { bleManager.unregisterStatusListener(it) }
        val listener = BikeStatusListener { status ->
            _uiState.update { it.copy(status = status) }
        }
        currentListener = listener
        bleManager.registerStatusListener(listener)
    }

    private fun stopMonitoring() {
        currentListener?.let { bleManager.unregisterStatusListener(it) }
        currentListener = null
    }
}

